from rb_lib import *


def clean(s): return s.strip("\n")
def oerr(c):
    t = c["openssl_error"]
    if c["rc"] == 0: return "exit 0 – CMS Verification successful"
    if "Verify error: " in t: return "exit %d – %s" % (c["rc"], t.split("Verify error: ")[-1])
    if "content verify error" in t: return "exit %d – content verify error (digest mismatch)" % c["rc"]
    return "exit %d – %s" % (c["rc"], t[-80:])


def build():
    H1("PART II – SECURITY ENGINEERING: IMPLEMENT, TEST, ATTACK AND HARDEN")
    P("Every table in Part II is generated from the JSON files written by the experiment programs (Appendix A lists them), so the report cannot drift from the evidence. Predictions are quoted as written in the program **before** execution; the ‘match’ column is computed by the program. All keys are test keys created at run time; no private key is printed or stored in the source.", 9.5, italic=True)
    t1 = J("t1"); t2 = J("t2"); t3 = J("t3")

    # ============================================================= TASK 1
    H2("TASK 1 – A PGP-STYLE SECURE MAIL ENGINE (8 marks)", True)
    P("**Implementation** (`pgpmail.py`, Appendix B): hybrid design from Part I Task 2 – `RSA-PSS(SHA-256)` signature over the message, `zlib` compression of `signature ‖ message`, a fresh `AES-256-GCM` session key, `RSA-OAEP(SHA-256)` wrapping per recipient, radix-64 armour. The GCM additional-authenticated-data is the whole header (recipient list included), so changing the recipient list or any wrapped key is detected. The tool has a command line (`protect`, `unprotect`), a public key ring with owner-trust and certifications (the web of trust of Part I Task 5), and returns a **distinct non-zero exit status** for each failure class.")
    H3("Task 1.1 – Working sender and receiver (3 marks)")
    P("A real run through the command-line interface (User 1 = Alice, User 2 = Bob, message “MEET AT 9”). The sender prints only the **session-key identifier** (the first 8 bytes of SHA-256(Ks)), never the key.")
    CODE(clean(t1["normal_protect"]["out"]), 7.6, title="Sender: `pgpmail.py protect --sender alice --to bob …`  (exit status %d)" % t1["normal_protect"]["code"])
    CODE(clean(t1["normal_unprotect"]["out"]), 7.6, title="Receiver: `pgpmail.py unprotect --me bob …`  (exit status %d)" % t1["normal_unprotect"]["code"])
    P("The receiver reports the decrypted message, the **signature result** (‘cryptographically VALID’), the **signer identity** (alice, found by key ID) and the **trust result** (the web-of-trust evaluation: VALID because Carol is a full introducer and Dave and Eve are two marginal ones). Component layout of the protected message:")
    FIG("t1_layout", 6.5, "Layout of the protected message; the header is authenticated as AES-GCM associated data.", "fig_t1layout")
    CAPT("t1exit", "Failure handling: exit status and message for each failure class (all verified in Task 1.4 below)")
    TBL(["Exit", "Meaning", "When"], [["0", "success, signer key validated", "all checks pass"], ["2", "malformed / truncated armour", "decoding or length fields fail"], ["3", "not a recipient / no usable recipient key", "key ID not in recipient list; expired or revoked recipient key on the sender side"], ["4", "session-key unwrap failed", "wrapped key corrupted, or wrong key"],
        ["5", "authentication tag mismatch", "ciphertext or header modified"], ["6 / 7 / 8 / 9", "decompression failure / unknown sender / signature invalid / sender key revoked or expired", "inner checks"], ["20", "signature valid but signer key **not validated** by the web of trust", "UNKNOWN validity: output plus a warning on stderr"]], [0.9, 2.8, 2.9], 8.3)
    H3("Task 1.2 – Intermediate values, key-to-operation mapping and a labelled view (2 marks)")
    CAPT("t1map", "Which key is used for which operation, and what each check proves")
    TBL(["Step", "Operation", "Key used", "What it provides / the check that passed"], [
        ["Sender 1", "SHA-256 digest of M (computed inside RSA-PSS signing)", "–", "fixed-size input to the signature (message was 9 bytes)"], ["Sender 2", "RSA-PSS signature, 256 B", "**Alice’s private key**", "authentication + integrity; signature is made __before__ compression/encryption"],
        ["Sender 3", "zlib compression of `sig ‖ M` (267 B → 278 B for this tiny message)", "–", "compression after signing; tiny inputs can grow, long text shrinks (4,000 B → " + f"{t1['meas']['a']['sizes']['compressed']:,} B in Task 1.3)"], ["Sender 4", "session key id only (8 B of SHA-256(Ks))", "fresh random Ks", "lets the receiver check it unwrapped the right key without revealing it"],
        ["Sender 5", "RSA-OAEP wrap of Ks, 256 B", "**Bob’s public key**", "only Bob’s private key can recover Ks"], ["Sender 6", "AES-256-GCM(Ks) of the compressed block, header as AAD, 16 B tag", "**session key Ks**", "confidentiality + integrity of payload and header"],
        ["Receiver 1–2", "radix-64 decode; header parse; ‘am I a recipient?’", "–", "recipient key ID found"], ["Receiver 3", "RSA-OAEP unwrap; session-key-id check", "**Bob’s private key**", "Ks recovered, matches the ID"],
        ["Receiver 4–5", "GCM tag verified; decompress; split signature and message", "Ks", "**passed check:** ciphertext and header unmodified"], ["Receiver 6", "RSA-PSS verify", "**Alice’s public key** (found by key ID)", "**passed check:** signature valid → cryptographically from the holder of Alice’s key"],
        ["Receiver 7", "web-of-trust evaluation of Alice’s key (4 introducer signatures verified)", "Carol, Dave, Eve, Frank public keys", "**passed check:** key VALID (full = 1, marginal = 2)"]], [0.8, 2.5, 1.35, 1.95], 8)
    CAPT("t1hex", "Labelled hex view of the protected message (first 16 bytes of each field)")
    TBL(["Field", "Offset", "Length (B)", "Bytes (hex)"], [[h["label"], f"{h['start']}–{h['end']-1}", str(h["length"]), "`" + h["hex"] + "`"] for h in t1["hexview"]], [2.7, 0.9, 0.8, 2.3], 8)
    P("The first 4 bytes are the magic number ‘PGPX’ (`50 47 50 58`), then version 1, one recipient, the session-key ID and sender key ID, then Bob’s key ID with the length of the wrapped key (0x0100 = 256), the OAEP-wrapped session key (random-looking), the 12-byte GCM nonce, the ciphertext length, and finally the ciphertext with its 16-byte tag. Armoured text begins " + "`" + t1["small_armor_head"][1][:40] + "…`" + " (base64 of these bytes).", 9.5)
    H3("Task 1.3 – Predictions versus measurements: one recipient, five recipients, 10× size (2 marks)")
    m = t1["meas"]; pa = t1["pred"]
    P("**Predictions written before the run.** (a) one recipient, 4 KB: public-key operations at the sender = 2 (one signature + one wrap), symmetric = 1; header = 23 + 266 = 289 bytes. (b) five recipients: public-key operations = 6; the header grows by exactly 4 × 266 = 1,064 bytes; the compressed payload is unchanged. (c) 10× message size (40 KB): public-key and symmetric __operation counts__ unchanged (2 and 1); the ciphertext grows, **by at most 10×** because compression improves on longer text; the sender’s time grows with message size but not with a recipient-count effect of the same order.")
    CAPT("t1pred", "Predictions and measurements (median of 15 runs for time)")
    rows = []
    for k, lab in (("a", "a: 1 recipient, 4 KB"), ("b", "b: 5 recipients, 4 KB"), ("c", "c: 1 recipient, 40 KB")):
        x = m[k]; rows.append([lab, f"{pa[k]['pk_sender']} / {x['pk']}", f"{pa[k]['sym']} / {x['sym']}", str(x["sizes"]["header"]), str(x["sizes"]["compressed"]), str(x["sizes"]["ciphertext"]), str(x["sizes"]["binary"]), f"{x['time_ms']:.2f}", f"{x['recv']['pk']} (2 + {x['recv']['pk']-2} key-validation)", "yes" if x["recv"]["ok"] else "NO"])
    TBL(["Case", "PK ops pred / actual", "Sym ops pred / actual", "Header B", "Compressed B", "Cipher B", "Total binary B", "Sender ms", "Receiver PK ops", "Round trip OK"], rows, [1.2, 0.7, 0.7, 0.5, 0.65, 0.5, 0.65, 0.5, 0.95, 0.5], 7.5, align=["l", "c", "c", "c", "c", "c", "c", "c", "c", "c"])
    FIG("t1_sizes", 4.6, "Message size split into recipient entries (header) and encrypted payload for the three cases.", "fig_t1sizes")
    d_hdr = m["b"]["sizes"]["header"] - m["a"]["sizes"]["header"]; ratio = m["c"]["sizes"]["ciphertext"] / m["a"]["sizes"]["ciphertext"]
    P(f"**Interpretation.** Operation counts matched exactly: public-key work is **per recipient** (2 → 6) and independent of message size (case c: still 2), while the symmetric cipher is invoked once per message in every case (its __byte volume__ scales with size, its __operation count__ does not). Message size: b − a = **{d_hdr} bytes = 4 × 266**, the prediction exactly; the payload part is unchanged (±{abs(m['b']['sizes']['compressed']-m['a']['sizes']['compressed'])} B from compression variance of a different random session wrap). Case c grew by a factor of **{ratio:.1f}** in ciphertext, less than the 10× upper bound because the longer text compresses better (compressed 40 KB → {m['c']['sizes']['compressed']} B). Timing: the dominant cost of a small message is the single RSA signature (≈ 0.5 ms in this Python run); five recipients add four ≈ 0.05 ms wraps, whereas the 40 KB message is dominated by compression (case c sender time ≈ {m['c']['time_ms']/m['a']['time_ms']:.1f}× case a). The receiver’s extra public-key operations in the table are the four certification signatures verified to validate Alice’s key – they are key-validation work, not message work, and could stop after the first full introducer (3 operations in total).", 9.5)
    H3("Task 1.4 – Boundary and tamper tests (1 mark)")
    P("**Selection.** The tests were chosen to attack each layer of the design: __bit-flip in the ciphertext__ (does the authenticated encryption reject silent modification?); __bit-flip inside the wrapped key__ (does a corrupted RSA-OAEP block fail safely?); __non-recipient with a valid key__ (is the recipient list enforced before any decryption?); __signer not validated__ (is cryptographic validity kept distinct from identity trust?); __empty message__ (zero-length boundary); __truncation__ (malformed input). Each run goes through the command-line tool so the exit status is the observable.")
    CAPT("t1tamper", "Boundary / tamper tests with observed behaviour")
    TBL(["Test", "Why chosen", "Exit", "Observed behaviour"], [[b["name"], b["why"], str(b["code"]), (b["err"] or b["out"])[:150]] for b in t1["boundary"]], [1.2, 2.2, 0.4, 2.8], 7.6, align=["l", "l", "c", "l"])
    P("**Safe failure.** Every failure is **fail-closed**: no plaintext is released on a tag mismatch, unwrap failure or non-recipient request; messages differ only in the status code and reason, and the secret session key is never written to any log. The two exit-20 cases show the intended separation: the signature is __mathematically__ valid, but because Gina’s key has one marginal introducer and Mallory’s only an untrusted one, the engine will not call the identity trusted.")
    BOX("Rubric check – Task 1 (8)", ["1.1 ✔ working CLI, session-key ID only, structure, decrypted text + signature result + signer identity, distinct exit codes.  1.2 ✔ intermediate sizes, key-to-operation table, passed checks, labelled hex view.  1.3 ✔ predictions vs actual for 1 / 5 / 10×, operation counts, size trend.  1.4 ✔ seven boundary/tamper tests with reasons."])

    # ============================================================= TASK 2
    H2("TASK 2 – S/MIME ENGINEERING AND COMPARISON WITH PGP (9 marks)", True)
    P("**Test PKI (`pki.py`).** Root CA (pathLen 1) → Issuing CA (pathLen 0, CA:true) → end-entity certificates for user1, user2 (S/MIME and client-auth), plus purpose-built defective ones (expired, wrong address, revoked, rogue-CA). S/MIME is performed with the OpenSSL CMS implementation (`openssl cms`), and a student-written validator (`validate_signer`, the repaired Part I Task 4.3 logic) explains each decision step by step.")
    FIG("t2_pki", 6.3, "Certificate hierarchy used for S/MIME and TLS, with the failure cases of Task 2.2.", "fig_pki")
    H3("Task 2.1 – Normal case, User 1 → User 2 (2 marks)")
    sn = t2["smime_normal"]
    CAPT("t2normal", "S/MIME signed-then-encrypted message from User 1 to User 2: commands and results")
    TBL(["Step", "Command (abridged)", "Result"], [["Sign (User 1)", "`openssl cms -sign -signer user1.pem -inkey user1.key -certfile inter.pem`", f"exit {sn['steps']['sign']['rc']}; signature + User 1 and Issuing-CA certificates embedded"],
        ["Encrypt (to User 2)", "`openssl cms -encrypt -recip user2.pem -aes-256-cbc`", f"exit {sn['steps']['encrypt']['rc']}; RSA key transport of a random content-encryption key for User 2"], ["Decrypt (User 2)", "`openssl cms -decrypt -recip user2.pem -inkey user2.key`", f"exit {sn['steps']['decrypt']['rc']}"],
        ["Verify (User 2)", "`openssl cms -verify -CAfile root+CRL -crl_check -verify_email user1@hospital.test`", f"exit {sn['steps']['verify']['rc']}: “{sn['steps']['verify']['err']}”; recovered text identical to the original: **{sn['plaintext_ok']}**"]], [1.1, 3.4, 2.1], 8)
    P("**Receiving-side validation sequence and signer identity.** The student validator, run on the signer certificate that OpenSSL extracted from the message, produced the following checks (3 certificate signatures/CRL operations performed):")
    CODE("\n".join(sn["validator"]["log"]) + f"\n=> {sn['validator']['decision']}: {sn['validator']['reason']}", 7.6)
    P(f"The **signer identity** is “{sn['signer_subject']}” (issuer: “{sn['signer_issuer']}”) and the trust explanation is __structural__: the message is trusted because the certificate chains through the Issuing CA to the one root the recipient already trusts, is in date, is allowed to sign mail, names exactly the address in the message, and is not revoked. `openssl verify -show_chain` gives the same chain:", 9.5)
    CODE(clean(t2["openssl_verify_chain"]), 7.6)
    pn = t2["pgp_normal"]
    P("**PGP normal case (same message, User 1 = Alice → User 2 = Bob, Task 1 engine).** Receiving-side sequence: unwrap session key → GCM tag → decompress → signature verified with Alice’s key (found by key ID) → web of trust: " + "; ".join(x.replace("web-of-trust: ", "") for x in [l.strip() for l in pn["lines"] if "web-of-trust" in l]) + f". Result: **{pn['trust']}** – Alice’s key is VALID because of one full and two marginal introducers.", 9.5)
    H3("Task 2.2 – Trust-failure cases, with predictions (3 marks)")
    P("Seven S/MIME cases were prepared. For each, the prediction below was fixed in the program first, then OpenSSL’s verifier was run with the CRL, trusted-root and address options of the receiver, and the student validator was run on the same certificate.")
    cs = t2["smime_cases"]
    CAPT("t2cases", "S/MIME trust-failure cases: prediction, first rejecting check and error output")
    TBL(["Case", "Scenario", "Predicted first rejecting check", "OpenSSL result (error text)", "Student validator", "Match"], [[c["id"], c["title"], c["predict"], oerr(c), (c["validator"] + " – " + str(c["validator_reason"])) if c["validator"] == "REJECT" else (c["validator"] + " (chain/identity/revocation; the CMS content digest is a separate check)"), "✔" if c["matched"] else "✘"] for c in cs],
        [0.4, 1.5, 1.45, 1.4, 1.4, 0.4], 7.3, align=["c", "l", "l", "l", "l", "c"])
    s5 = [c for c in cs if c["id"] == "S5"][0]
    P(f"**Reading the table.** S1 is stopped at the validity period; S2 and S6 both fail with ‘unable to get local issuer certificate’ although for opposite reasons – S2 because the issuer is __not trusted__ (rogue root), S6 because a __trusted__ issuer’s certificate is missing from the message (S7 shows the same message passes once the intermediate is attached, proving it was a missing-chain defect and not a forgery); S3 passes the signature and the chain but fails the identity check; S4 is stopped by the CRL; S5 passes every certificate check – the student validator accepts the certificate, which is correct – and is stopped only by the **content digest** (“content verify error”), a different layer: signature over the data, not trust in the key.", 9.5)
    gp = t2["pgp_untrusted"]
    P("**PGP insufficient-trust case.** Gina’s key carries one marginal signature (Dave). The Task 1 engine produced:")
    CODE("\n".join(l for l in gp["lines"][-4:]) + "\n" + "(exit status 20)  WARNING: signature is mathematically valid but the signer's key is NOT validated by your web of trust", 7.6)
    P("**Cryptographic validity versus identity trust.** In every case above two different questions were answered by two different mechanisms: __Was this data signed by the private key matching this public key?__ (CMS signature / PGP signature – true in S1–S4, S6 and the Gina case) and __Is this public key really that person’s?__ (chain, address, revocation / web of trust – false in each failing case). A valid signature answers only the first; S/MIME rejects on the second, PGP downgrades to a warning – a policy difference examined in Task 2.4.", 9.5)
    H3("Task 2.3 – Evidence-based comparison (2 marks)")
    cm = t2["comparison"]; sz = t2["smime_sizes"]
    CAPT("t2cmp", "S/MIME versus PGP-style for the same 4,000-byte message, User 1 → User 2")
    TBL(["Measure", "S/MIME (OpenSSL CMS)", "PGP-style (Task 1 engine)", "Observation"], [
        ["Public-key operations, **sender**", f"{cm['smime']['sender_pk']} (1 sign, 1 key transport)", f"{cm['pgp']['sender_pk']} (1 sign, 1 wrap)", "identical"],
        ["Public-key operations, **receiver**", f"{cm['smime']['receiver_pk']} (1 decrypt, 1 signature verify, {cm['smime']['chain_verifies']} chain/CRL verifies)", f"{cm['pgp']['receiver_pk']} ({cm['pgp']['receiver_message_path']} message path + {cm['pgp']['receiver_key_validation']} introducer-signature verifies)", "trust work dominates both; PGP’s 4 could be 1 with early exit"],
        ["Message size", f"{cm['smime']['msg_bytes_der']} B binary (DER), {cm['smime']['msg_bytes_pem']} B as S/MIME text", f"{cm['pgp']['msg_bytes_bin']} B binary, {cm['pgp']['msg_bytes']} B armoured", f"PGP engine compresses (4,000 → {pn['sizes']['compressed']} B); the S/MIME run did not"],
        ["**Per-message certificate overhead**", f"{cm['smime']['cert_overhead']} B (signer + intermediate certificates attached to __every__ message)", "0 B (keys are exchanged once into the ring)", "S/MIME is self-contained; PGP needs the ring to be prepared"],
        ["One-off key material for the sender", f"{sz['leaf_der']} B certificate", f"{cm['pgp']['key_overhead']} B (public key + {pn['key_overhead']['certification_sigs']} certification signatures)", "similar magnitude"],
        ["**Unknown sender**", "validated automatically: build path to the root already trusted (no prior contact)", "UNKNOWN unless a trusted-enough introducer path exists (Gina: warning, exit 20)", "decisive difference"],
        ["**Trust dependency**", "**CA hierarchy**: one anchor; blast radius = subtree of a compromised CA", "**Introducers**: many local trust decisions; a single marginal introducer has no power alone", "see Task 2.4"]], [1.4, 2.0, 1.8, 1.4], 7.7)
    H3("Task 2.4 – Choice for 5,000 users across organisations (2 marks)")
    sc = t2["scaling"]
    P("The right panel of Figure {{fig_spam}} (Part I, Task 5) plots the result below: share of ‘stranger’ keys a verifier can validate in a web of trust of 5,000 users (Monte-Carlo, 200,000 random pairs for each setting), versus a CA hierarchy.", 9.5)
    CAPT("t2scale", "Web-of-trust simulation, N = 5,000 users")
    TBL(["Verifier’s fully trusted contacts", "Introducer signatures on each key", "Pairs where the sender’s key validates (PGP)", "S/MIME (one trust anchor)"], [[str(s["contacts"]), str(s["signers"]), f"{s['pgp_valid_fraction']*100:.1f} %", "100 % (every certificate chains to the same root)"] for s in sc], [1.7, 1.5, 1.8, 1.6], 8.2, align=["c", "c", "c", "l"])
    P("**Decision: S/MIME with a hierarchical CA for the 5,000-user, multi-organisation deployment.** Evidence from 2.1–2.3: (i) the per-message __cryptographic__ cost is identical (2 sender operations; the receiver’s trust work is 5 operations for S/MIME and 6 for PGP as implemented); (ii) the S/MIME message carries its own chain (+1,794 bytes), so a stranger can be validated with no prior contact, whereas PGP keys validated in only 2–88 % of random pairs depending on how many introducers each user personally trusts – reaching a high percentage required each user to trust hundreds of introducers, i.e. a manual trust decision per person at 5,000-user scale; (iii) revocation and expiry are checked mechanically through CRL/OCSP, giving a rejection (S4) where the web of trust gives only a warning (exit 20). **Costs accepted:** a compromised intermediate CA invalidates trust for its whole subtree (Part I Task 5.2), so intermediates are constrained (`pathLen = 0`, name constraints) and the root is offline; organisations must exchange root certificates or use a bridge CA; and the 1.8 KB/message certificate overhead is tolerable. PGP remains appropriate for small groups without a CA, where the web of trust needs no infrastructure.", 9.5)
    BOX("Rubric check – Task 2 (9)", ["2.1 ✔ both normal cases, validation sequence, signer identity and trust explanation.  2.2 ✔ seven S/MIME cases with prediction, first check, error output; PGP warning; cryptographic validity vs trust.  2.3 ✔ operations, sizes, certificate overhead, unknown sender, trust dependency.  2.4 ✔ reasoned choice for 5,000 users backed by the measurements and the simulation."])

    # ============================================================= TASK 3
    H2("TASK 3 – SECURING THE IP LAYER: ESP PROCESSING AND ATTACK LAB (10 marks)", True)
    P("`esp.py` implements an ESP-like **tunnel-mode** gateway (AES-256-GCM as the combined cipher: the 16-byte GCM tag is the ICV, with `SPI ‖ Seq` as associated data), an inbound SA database with the Part I Task 3 replay window, AH with immutable-field ICV, an IKE-like authenticated X25519 exchange with HKDF key derivation, and a NAT function. The processing order is exactly that of Part I Task 3.3: **SA lookup → ICV → replay check → window update → decapsulate**.")
    H3("Task 3.A – Tunnel-mode processing and packet trace (2 marks)")
    A = t3["A"]
    P(f"Gateway A (192.0.2.1) protects packets from host 10.1.0.5 to host 10.2.0.9 for gateway B (198.51.100.1). The SA (SPI {A['spi']}) was created by the IKE-like exchange; encapsulation adds the outer IP header (20 B), ESP header (SPI 4 B + sequence 4 B), IV (8 B), padding and trailer, and a 16-byte ICV: a {A['inner_len']}-byte inner packet becomes {A['inner_len']+A['overhead']} bytes (**overhead {A['overhead']} bytes**). First 48 bytes of the outer packet for sequence 6: `{t3['A_example_hex']}`.")
    CAPT("t3A", "Packet trace, gateway B (W = 32), six packets")
    TBL(["#", "SPI looked up", "Seq", "ICV", "Replay decision", "Highest", "Decapsulated: inner src → dst", "Payload", "Inner UDP checksum"], [[str(i + 1), A["spi"], str(r["seq"]), r["icv"], r["decision"] + " – " + r["reason"], str(r["highest"]), r["inner_src"] + " → " + r["inner_dst"], r["payload"], "valid" if r["udp_checksum_ok"] else "BAD"] for i, r in enumerate(A["rows"])],
        [0.25, 0.85, 0.35, 0.45, 1.1, 0.55, 1.35, 0.95, 0.55], 7.4, align=["c", "c", "c", "c", "l", "c", "l", "l", "c"])
    P("**Interpretation.** The SPI selects the SA; the ICV is verified before the sequence number is consulted; each new sequence number advances `Highest`; the inner packet is recovered unchanged (payload and checksum intact), which also shows that tunnel mode hides the inner addresses on the public path.", 9.5)
    H3("Task 3.B – Replay and reordering tests with predictions (3 marks)")
    B = t3["B"]
    P(f"Setup: window W = {B['W']}; packets 1…100 delivered in order except 60, 68, 69 and 84, which were captured but **withheld**; state before the tests: Highest = {B['state_before']['highest']}.")
    CAPT("t3B", "Replay / reordering tests (prediction fixed before execution)")
    TBL(["Test", "Description", "Predicted", "Actual", "Match"], [[r["tag"], r["desc"], r["predicted"], r["actual"], "✔" if r["match"] else "✘"] for r in B["rows"]], [0.5, 2.6, 1.7, 1.5, 0.4], 7.6, align=["c", "l", "l", "l", "c"])
    FIG("t3_boundary", 6.2, "Window state after packet 100 and the position of each tested packet.", "fig_boundary")
    P(f"**Interpretation.** All {len(B['rows'])} predictions held. Exact replay (i) and the second delivery of 84 (ii-b) are caught by the bitmap; the packet delayed by W/2 = 16 positions (ii) is __correctly accepted once__, because the receiver has never seen it – reordering inside the window is not an attack; the packet delayed by 40 > W positions (iii) is dropped although genuine – the cost of bounded memory. A captured packet with a **modified sequence number** (iv: 101, iv-b: 70 – a value that would otherwise be accepted as in-window) fails the ICV, so the window is never touched. The meaningful **boundary** pair is edge-in (seq 69 = Highest − W + 1, the oldest slot still inside, accepted) and edge-out (seq 68 = Highest − W, dropped): the off-by-one of the rule `d ≥ W` is exactly right.", 9.5)
    H3("Task 3.C – Payload tamper, unknown SPI, sequence exhaustion and information leakage (2 marks)")
    C = t3["C"]
    CAPT("t3C", "Failure-handling tests: internal log versus external response")
    TBL(["Case", "Internal log (reason)", "Highest / window", "External response"], [[r["case"], r["reason"], (str(r["internal_log"]["highest"]) + " / " + str(r["internal_log"]["window"])).replace("None / None", "n/a (no SA matched or packet unparsable)"), r["external_response"]] for r in C["rows"]], [1.4, 1.5, 1.2, 2.5], 8)
    P(f"**Sequence exhaustion and re-key.** A test SA with a maximum sequence number of 10 sent 10 packets; the 11th send was refused: “{C['exhausted']}”. A new child SA was then created by a fresh DH exchange (log: __{C['ike_log']}__); a packet protected under the new SPI was accepted by gateway B (`{C['rekey_accept']['decision']} – {C['rekey_accept']['reason']}`, SPI {hex(C['rekey_accept']['spi'])}, Highest = {C['rekey_accept']['highest']}) – the new SA starts with a **fresh window**. The old SA is kept briefly for packets in flight; after its deletion its SPI would produce UNKNOWN_SPI.")
    CAPT("t3tim", "Does the drop path leak which check failed? Median processing time of one packet (200 trials, µs)")
    TBL(["Packet kind", "Median µs", "90th percentile µs"], [[x["case"], f"{x['median_us']:.1f}", f"{x['p90_us']:.1f}"] for x in t3["timing"]], [2.6, 1.6, 1.8], 8.2, align=["l", "c", "c"])
